import random
from app import plan, replay

rng = random.Random(424242)
for i in range(3000):
    w, h = rng.randint(1, 6), rng.randint(1, 6)
    cells = [(x, y) for y in range(h) for x in range(w)]
    blocked = {p for p in cells if rng.random() < 0.2}
    start, goal = rng.choice(cells), rng.choice(cells)
    if start in blocked: blocked.discard(start)
    if goal in blocked: blocked.discard(goal)
    kwargs = {}
    if rng.random() < 0.4:
        kwargs["costs"] = [[rng.randint(1, 9) for _ in range(w)] for _ in range(h)]
    if rng.random() < 0.4:
        kwargs["dynamic_blocked"] = [
            [p for p in cells if rng.random() < 0.2]
            for _ in range(rng.randint(1, 6))
        ]
        frames = kwargs.get("dynamic_blocked")
        if frames and start in frames[0]:
            frames[0] = [p for p in frames[0] if p != start]
    # Build a random walk candidate (may be invalid in many ways).
    n = rng.randint(1, 8)
    path = [tuple(rng.choice(cells)) for _ in range(n)]
    path[0] = start if rng.random() < 0.8 else tuple(rng.choice(cells))
    path[-1] = goal if rng.random() < 0.8 else tuple(rng.choice(cells))

    a = replay(w, h, blocked, start, goal, path, **kwargs)
    b = replay(w, h, blocked, start, goal, path, diagnose=False, **kwargs)
    assert a == b and set(a) == {"valid", "cost", "steps"}, (a, b)

    d = replay(w, h, blocked, start, goal, path, diagnose=True, **kwargs)
    assert set(d) == {"valid", "cost", "steps", "error", "error_index"}
    assert d["valid"] == a["valid"]
    if a["valid"]:
        assert d["cost"] == a["cost"] and d["steps"] == a["steps"]
        assert d["error"] is None and d["error_index"] is None
    else:
        assert d["cost"] is None and d["steps"] is None
        assert d["error"] in {"start_mismatch", "goal_mismatch",
                              "start_goal_extra", "repeated_coordinate",
                              "non_adjacent", "static_blocked",
                              "dynamic_blocked"}
        assert isinstance(d["error_index"], int) and 0 <= d["error_index"] < len(path)

# plan must be untouched.
p = plan(6, 4, {(2, 0), (2, 1), (2, 2)}, (0, 0), (5, 3), trace=True)
assert set(p) == {"path", "cost", "expanded", "expanded_nodes"}
print("differential check OK")
